// News articles. Titles and categories come from catalog.ts; this file adds the long-form copy.
// Image ids point at the image manifest (plan 04). `links` are deliberate raw material for plan 07
// (PDF links, vague "Read more" links).
import { newsArticles } from "../catalog";

export type NewsBlock = string | { h2: string };

export interface NewsLink { label: string; href: string }

export interface NewsArticle {
  slug: string;
  title: string;
  category: string;
  /** ISO date, YYYY-MM-DD. */
  date: string;
  author: string;
  authorTitle: string;
  dek: string;
  image: string;
  imageCaption: string;
  body: NewsBlock[];
  related: string[];
  links?: NewsLink[];
}

type ArticleDetails = Omit<NewsArticle, "slug" | "title" | "category" | "image">;

const details: Record<string, ArticleDetails> = {
  "tide-pool-study-coastal-warming": {
    date: "2026-06-24",
    author: "Dana Whitaker",
    authorTitle: "Office of Research Communications",
    dek: "Fourteen years of temperature readings and monthly surveys from the Arcadia coast show tide pools warming faster than the open ocean, with sea stars and mussels feeling the heat first.",
    imageCaption: "Biology students survey a tide pool at Gull Rock Point during a minus tide in April.",
    body: [
      "At 5:40 on a foggy April morning, a dozen Redwood State biology students crouched over the rocks at Gull Rock Point with clipboards, quadrats and headlamps, racing the incoming tide. They were doing what RSU students have done at least once a month since 2012: counting every sea star, anemone and snail in a set of permanently marked tide pools and swapping out the small temperature loggers bolted into the rock.",
      "Those monthly visits have added up. In a study published this spring in Annals of Coastal Ecology, a team led by Naomi Begay, Ph.D., associate professor of biology, reports that water temperatures in Arcadia's tide pools have risen by an average of 1.1 degrees Celsius since monitoring began, roughly twice the rate of warming measured in nearby offshore waters over the same period.",
      "“Tide pools are where the ocean meets the atmosphere twice a day,” Begay said. “When a low tide lands on a warm, clear afternoon, a pool that was 12 degrees in the morning can hit 25 degrees by three o’clock. What we’re seeing is that those extreme afternoons are becoming much more common, and the animals living there have no way to leave.”",
      { h2: "A record built one low tide at a time" },
      "The study draws on more than 480,000 individual temperature readings, logged every fifteen minutes by instruments at 36 pools spread across four sites between Gull Rock Point and the mouth of the Silverfin River. Each month, students also photograph and survey fixed plots, producing a record of which species are present and how abundant they are.",
      "Begay credits the students, many of whom were not yet in kindergarten when the project began. More than 300 undergraduates have contributed data over fourteen years, and at least a dozen have written senior theses from the dataset.",
      "“There is nothing glamorous about checking a logger in the rain at 5 a.m.,” said Ethan Park, Ph.D., assistant professor of biology and a co-author on the paper. “But that consistency is exactly what makes this record valuable. Most long-term datasets like this come from big research stations. This one came from students with rubber boots and a tide table.”",
      { h2: "Sea stars and mussels under stress" },
      "The warming has not been felt evenly. The team found that the number of days per year when pool temperatures exceeded 22 degrees Celsius, a threshold associated with stress in many intertidal invertebrates, tripled between the first five years of the study and the most recent five.",
      "Ochre sea stars, which were devastated along the West Coast by a wasting disease outbreak beginning in 2013, have made a partial recovery at Arcadia sites but remain about 40 percent below their pre-outbreak numbers. The researchers found that recovery was slowest in the shallowest, warmest pools. California mussel beds, which provide habitat for dozens of smaller species, have also thinned at the highest points on the shore.",
      "Park’s lab is now using environmental DNA collected from pool water to detect species that are hard to spot by eye, including juvenile sea stars and small crustaceans. Early results suggest that some southern species not previously recorded at Arcadia are beginning to appear.",
      { h2: "What comes next" },
      "Begay says the goal is not only to document change but to give coastal managers and tribal natural resource staff information they can act on. The team shares its data with regional monitoring networks and is working with the county to identify pools that stay cooler, which could serve as refuges for vulnerable species.",
      "The project has also become a gateway to science for students. Senior biology major Alondra Reyes, who has helped with surveys since her first semester, says the early mornings changed her plans. “I came in thinking I would go to pharmacy school,” she said. “Now I’m applying to graduate programs in marine ecology. I’ve seen these pools change in four years. I want to understand why.”",
      "The research was supported by the RSU Office of Research and Sponsored Programs, a state coastal protection grant and donors to the Marine Biology Field Fund. Students interested in joining monthly surveys can contact the Department of Biology; no experience is required, but waterproof boots are strongly recommended.",
    ],
    related: ["redwood-canopy-carbon-study", "alumna-salmon-sensor-startup", "wildfire-smoke-sensor-network"],
  },

  "engineering-robotics-lab-opens": {
    date: "2026-09-02",
    author: "Jenna Albright",
    authorTitle: "University Communications",
    dek: "The 9,000-square-foot Robotics and Autonomous Systems Lab gives students room to build, test and fly, from canopy-climbing robots to soft exosuits for farmworkers.",
    imageCaption: "Mechanical engineering students test a mobile robot on the new lab's open test floor.",
    body: [
      "For years, Redwood State’s robotics students built their projects wherever they could find space: in a converted storage room in the basement of Sequoia Engineering Hall, on folding tables in the hallway, and occasionally in a faculty member’s garage. This semester, they have a home.",
      "The new Robotics and Autonomous Systems Lab officially opened on August 28 with a ribbon cutting attended by students, faculty, donors and community partners. Occupying most of the renovated first floor of Sequoia Engineering Hall, the 9,000-square-foot facility includes an open, two-story test floor with a motion-capture system, a netted flight cage for drones, a fabrication bay with 3D printers and a laser cutter, a wet lab for soft robotics, and a dedicated space for student clubs.",
      "“This lab says to our students, you belong in this field and we are going to give you the tools to prove it,” said Kenji Watanabe, Ph.D., professor of mechanical engineering, who led the planning effort and now serves as the lab’s director. “Five years ago we had one robot arm, and students signed up for time on it in a binder. Now they can walk in, build something and test it the same afternoon.”",
      { h2: "Built for collaboration" },
      "The lab is shared between the Mechanical Engineering and Computer Science departments, reflecting the way modern robotics blends hardware, software and data. Watanabe’s group will use the test floor to develop the next version of its tree-climbing robot, designed to carry scientific instruments into the upper canopy of old-growth redwoods. Luis Ortega, Ph.D., assistant professor of mechanical engineering, has set up the soft robotics wet lab, where his students cast silicone actuators and test a wearable exosuit designed to reduce back strain for agricultural and mill workers.",
      "Computer science faculty are also moving in. Anjali Raman, Ph.D., professor of computer science, said her Inclusive Interaction Lab will use the space to study how people with mobility disabilities interact with assistive robots. “Robots that work in homes and workplaces need to work for everyone,” Raman said. “Having engineers, programmers and the people who will actually use these systems in the same room changes the questions you ask.”",
      "The lab was designed with accessibility in mind, including adjustable-height workbenches, wide aisles around equipment and a control room with a viewing window at seated height.",
      { h2: "Open to students from day one" },
      "The lab will support Mechatronics, Robotics, Vibrations and Controls and the Senior Design sequence, and it will host the student Robotics Team, which competes in regional autonomous vehicle and underwater robotics competitions. Watanabe said the lab is intended to be used by first-year students as much as graduate researchers. Open lab hours for any engineering or computer science student will begin the week of September 14, with safety training offered every Monday.",
      "Junior mechanical engineering major Kai Hoffman, president of the Robotics Team, said the difference is already obvious. “Last year we assembled our competition robot on the floor of a hallway and had to pack it up every night,” he said. “Now we have a bench, a locker and a place to actually drive it. Honestly it feels a little unreal.”",
      { h2: "A public–private investment" },
      "The $6.8 million project was funded through a combination of state capital funds, a federal equipment grant and private gifts, including a leadership gift from alumni Richard and Ann Tolliver, both 1985 graduates of the College of Engineering. The renovation was part of a broader modernization of Sequoia Engineering Hall managed by the Division of Administration and Finance.",
      "“This is exactly the kind of investment Wide Branches: The Campaign for Redwood State was designed for,” said Thomas Harlan, J.D., vice president for university advancement. “It connects our students to the future of their field and connects our alumni to the next generation of engineers.”",
      "Tours of the lab will be offered during Homecoming & Family Weekend in October. Faculty and industry partners interested in collaborating with the lab can contact the College of Engineering.",
    ],
    related: ["wildfire-smoke-sensor-network", "redwood-canopy-carbon-study", "madrone-hall-opens"],
    links: [{ label: "Read more", href: "/academics/colleges/engineering" }],
  },

  "redwood-canopy-carbon-study": {
    date: "2026-07-22",
    author: "Dana Whitaker",
    authorTitle: "Office of Research Communications",
    dek: "By climbing and measuring hundreds of trees, RSU ecologists found that old-growth redwood crowns hold up to 30 percent more carbon than standard forest models assume.",
    imageCaption: "A researcher from the Canopy Ecology Lab measures a reiterated trunk nearly 80 meters above the forest floor.",
    body: [
      "Standard methods for estimating how much carbon a forest stores rely on measurements taken from the ground: a tree’s diameter at chest height, its overall height, and a set of equations that predict the rest. For most forests, that works well enough. For the tallest trees on Earth, it turns out, it does not.",
      "A new study from Redwood State’s Canopy Ecology Lab, published this month in the Pacific Journal of Forest Carbon, finds that the crowns of old-growth coast redwoods hold between 18 and 30 percent more aboveground carbon than widely used allometric models predict. The difference comes largely from the complex architecture of old redwood crowns, which can include dozens of secondary trunks, fused limbs and thick mats of canopy soil hundreds of feet in the air.",
      "“If you only look at these trees from the ground, you miss an entire world,” said Miguel Santos, Ph.D., professor of biology and the study’s lead author. “An old redwood isn’t one trunk with some branches on top. It’s more like a small forest growing on a forest. Once you climb up and measure it, the carbon numbers go up substantially.”",
      { h2: "Measuring the unmeasurable" },
      "Over six field seasons, Santos and a team of graduate and undergraduate students used technical climbing techniques to map the full three-dimensional structure of 112 trees in old-growth stands in the Tanoak Creek watershed and two nearby state parks. Climbers measured every trunk and major limb with tapes and laser rangefinders, sampled wood density and collected cores of canopy soil.",
      "Those measurements were combined with ground-based laser scanning and a new mathematical approach, developed with Olga Petrova, Ph.D., professor of mathematics, that uses tools from topology to describe how crowns branch and reiterate. The team also used a prototype climbing robot developed by Kenji Watanabe, Ph.D., professor of mechanical engineering, to place microclimate sensors in the upper crowns of trees too fragile to climb safely.",
      "“The branching structure of these crowns is where the extra carbon hides,” Petrova said. “Topology gives us a language for describing that structure in a way that can be scaled up from a hundred trees to an entire forest.”",
      { h2: "Implications for climate policy" },
      "The findings matter because old-growth redwood forests, though they cover only a small fraction of California, already store more carbon per acre than almost any other forest type on the planet. More accurate estimates could affect how these forests are valued in state carbon accounting and conservation planning.",
      "The study also raises concerns. Santos’s team found that trees in drier inland stands, where summer fog has declined over the past half century, had more crown dieback and less canopy soil than trees closer to the coast. “The same complexity that stores all this carbon depends on fog and moisture,” Santos said. “If the climate keeps drying, some of that carbon could be at risk.”",
      "Priya Natarajan, Ph.D., vice president for research and graduate studies, said the study reflects Redwood State’s distinctive position. “Very few universities in the world have old-growth redwood forest a short drive from campus,” she said. “This is research that almost nobody else is positioned to do, and our students are doing it with their own hands.”",
      { h2: "Students in the canopy" },
      "Nineteen students contributed to the fieldwork, all of whom completed the university’s technical tree-climbing certification. Graduate student Rhea Whitcombe, a co-author, spent more than 200 hours in the canopy over three summers. “The first time you pull yourself above the fog layer and see the tops of the other trees, it’s very hard to go back to a normal job,” she said.",
      "The research was funded by a state climate research program and the Canopy Ecology Endowment, established by alumni donors. Santos will discuss the findings as part of the Redwood Lecture Series this fall.",
    ],
    related: ["tide-pool-study-coastal-warming", "engineering-robotics-lab-opens", "green-chemistry-grant"],
  },

  "nursing-simulation-center-accreditation": {
    date: "2026-05-14",
    author: "Jenna Albright",
    authorTitle: "University Communications",
    dek: "The Nursing Simulation Center in Salal Hall is now one of only a handful of accredited simulation programs at public universities in Northern California.",
    imageCaption: "B.S.N. students respond to a simulated rapid response event in the Nursing Simulation Center.",
    body: [
      "The patient in Room 3 is struggling to breathe. His oxygen levels are dropping, his wife is asking questions nobody has time to answer, and the four nursing students at his bedside have about ninety seconds to figure out why.",
      "The patient is a high-fidelity manikin, his wife is a trained actor, and the whole scene is being run from a control room behind one-way glass. But for students in Redwood State’s School of Nursing, the experience is designed to feel as real as possible, and this spring it earned national recognition.",
      "The Nursing Simulation Center in Salal Hall has received full accreditation from the Healthcare Simulation Standards Council in the core area of teaching and education. The accreditation, which runs for five years, recognizes programs that meet rigorous standards for scenario design, debriefing, faculty training, and evaluation of learning outcomes.",
      "“Accreditation tells our students, our clinical partners and future employers that the training happening in this building meets the highest national standards,” said Patricia Nguyen, D.N.P., R.N., professor and director of nursing. “Simulation lets students practice the moments that are rare, high stakes and impossible to schedule in a real hospital, and it lets them make mistakes where no one gets hurt.”",
      { h2: "A two-year effort" },
      "The accreditation process took nearly two years and included a detailed self-study, documentation of every scenario the center runs, and a two-day site visit by external reviewers. The self-study was led by Aisha Rahman, M.S.N., R.N., clinical assistant professor and the center’s simulation coordinator.",
      "“We had to show not only that our scenarios are realistic, but that every one of them is tied to specific learning objectives and that we can measure whether students meet them,” Rahman said. “The reviewers spent a lot of time on debriefing, the conversation after a scenario. That’s where most of the learning happens, and it’s something our faculty have worked very hard on.”",
      "The center includes four simulated inpatient rooms, a labor and delivery suite, a home health apartment, a skills lab with twenty-four stations and two debriefing rooms. It runs more than 350 scenarios each academic year, ranging from routine medication administration to sepsis, postpartum hemorrhage and end-of-life care. Actors from the Arcadia Falls community play family members and patients in many scenarios.",
      { h2: "Meeting a regional need" },
      "The accreditation comes as hospitals across the North Coast continue to face nursing shortages. Nguyen said simulation has allowed the School of Nursing to increase enrollment even as clinical placement slots at regional hospitals have become harder to find. State rules allow a portion of required clinical hours to be completed in simulation, and accreditation strengthens the school’s ability to use those hours effectively.",
      "Michael Harjo, Ph.D., R.N., associate professor of nursing, said the center is also used for scenarios that reflect the communities students will serve, including rural home visits and care for patients who must travel long distances to reach a hospital. “Our graduates are going to practice in places where the nearest ICU might be two hours away,” he said. “We want them to have rehearsed that reality before they live it.”",
      "Students say the scenarios stay with them. “The first time I did a code in simulation my hands were shaking,” said senior nursing student Brianna Tso. “The first time I was part of a real rapid response during my clinical rotation, I knew exactly where to stand and what to do. That’s not an accident.”",
      "The center will host an open house for regional healthcare partners in the fall. Prospective students can tour the facility during admissions visit days.",
    ],
    related: ["first-gen-scholars-expands", "sleep-study-later-classes"],
    links: [
      { label: "Read more", href: "/academics/departments/nursing" },
      { label: "B.S.N. Program Handbook 2025–26 (PDF)", href: "/documents/bsn-program-handbook-2025-26.pdf" },
    ],
  },

  "womens-soccer-conference-title": {
    date: "2026-10-02",
    author: "Colin Reyes",
    authorTitle: "Athletics Communications",
    dek: "A 2–1 win over Summit State at Redwood Field gave the Owls the Pacific North Conference regular-season crown with two matches to spare, ending a 17-year drought.",
    imageCaption: "Owls players celebrate at midfield after clinching the Pacific North Conference title at Redwood Field.",
    body: [
      "When the final whistle blew at Redwood Field on Thursday night, Maya Delgado dropped to her knees at midfield, then was immediately buried under a pile of teammates. In the stands, a crowd of more than 1,800, the largest for a women’s soccer match in program history, was already on its feet.",
      "With a 2–1 win over Summit State, the Redwood Owls clinched the Pacific North Conference regular-season championship, their first conference title since 2009. The Owls improved to 10–1–1 overall and 6–0–0 in conference play, with two league matches remaining on the compressed fall schedule.",
      "“I told them before the game that nobody remembers the team that almost did it,” said head coach Andrea Whitlock, now in her sixth season. “They went out and made sure they’d be remembered. I could not be prouder of this group.”",
      { h2: "A match that tested everyone" },
      "Summit State struck first in the 23rd minute, when a corner kick skipped through a crowded box and was headed in at the far post. It was only the fourth goal the Owls had allowed all season, and for the rest of the half the visitors packed ten players behind the ball.",
      "The equalizer came just after halftime. Delgado, a senior forward and the conference’s leading scorer, collected a long ball on the left wing, cut inside two defenders and curled a shot into the upper corner from 20 yards. It was her 13th goal of the season.",
      "The winner came in the 78th minute, from an unlikely source. Junior defender Sierra Blackwood, who had not scored all season, pushed forward on a set piece and redirected a Delgado free kick off her shin and into the net.",
      "“I’m going to say I meant it,” Blackwood said, laughing. “Honestly I just closed my eyes and stuck my leg out. Maya puts the ball exactly where it needs to be. I just had to be there.”",
      { h2: "From rebuilding to champions" },
      "The title caps a remarkable turnaround. When Whitlock arrived in 2021, the Owls were coming off a two-win season. She recruited heavily from Northern California club programs and the Pacific Northwest, and her 2023 recruiting class, including Delgado, is now the senior core.",
      "“We lost a lot of games my freshman year,” Delgado said. “We would ride the bus home from Oregon at two in the morning after losing 4–0 and coach would say, ‘We’re building something.’ It was hard to believe then. Tonight, I believe it.”",
      "Delgado has been named Pacific North Conference Offensive Player of the Week three times this season and is on the watch list for regional player of the year. Blackwood anchors a back line that has recorded eight shutouts.",
      { h2: "What’s next" },
      "The regular-season title guarantees the Owls the top seed and home-field advantage throughout the Pacific North Conference Tournament, which begins October 30. It also strengthens their case for an at-large bid to the national tournament should they fall in the conference playoffs.",
      "Before that, the Owls close the regular season with a road trip to Cascade State on October 9 and a home match against Cedar Valley University on October 24, which will double as the Homecoming game. The program will honor the 2009 championship team at halftime.",
      "“Those women set the standard,” Whitlock said. “It means a lot to have them back on this field to see what they started.”",
      "Tickets for the Homecoming match are free for RSU students with a valid ID and $8 for the general public. Fans who can’t make it can watch the stream on the Owls athletics website.",
    ],
    related: ["mens-basketball-season-preview", "cross-country-all-american"],
    links: [{ label: "Full results and box score", href: "/athletics/scores" }],
  },

  "first-gen-scholars-expands": {
    date: "2026-08-19",
    author: "Jenna Albright",
    authorTitle: "University Communications",
    dek: "Nearly 500 students will take part in the program this year, which pairs first-generation college students with mentors, a summer bridge experience and a dedicated study space.",
    imageCaption: "First-Generation Scholars gather on Canopy Green during the program's summer bridge week.",
    body: [
      "When Yesenia Lopez arrived at Redwood State as a first-year student in 2023, she did not know what a syllabus was, had never heard the phrase “office hours,” and was too embarrassed to ask. “My parents were so proud of me, but they couldn’t help me figure out any of it,” she said. “I felt like everybody else got a manual that I never received.”",
      "Three years later, Lopez is a senior psychology major, a peer mentor and one of the most visible faces of the First-Generation Scholars Program, which this fall welcomes its largest cohort ever. With support from new state funding and private gifts, the program has grown from 240 participants in 2024–25 to nearly 500 this year.",
      "About 46 percent of Redwood State undergraduates are the first in their families to attend a four-year college, one of the highest shares among public universities in California.",
      "“First-generation students are not a problem to be solved. They are the reason this university exists,” said Mei-Lin Chao, Ed.D., vice president for student affairs. “When Arcadia Falls Normal School opened in 1911, it was to educate the children of loggers and fishermen to become teachers. That mission hasn’t changed. What has changed is how intentionally we support it.”",
      { h2: "What the program offers" },
      "The First-Generation Scholars Program begins with a free, week-long summer bridge experience in August, where incoming students move into campus housing early, take a one-unit course on navigating college, meet faculty and learn to use tools like RedwoodConnect and the Sequoia Library catalog. Each scholar is then paired with a peer mentor and a faculty or staff mentor who was also a first-generation student.",
      "Throughout the year, scholars have access to a dedicated study lounge and advising center on the second floor of the Rowan Student Union, priority registration for their first two semesters, small emergency grants and monthly workshops on topics ranging from financial aid to applying for internships.",
      "Faculty mentors come from across campus. Luis Ortega, Ph.D., assistant professor of mechanical engineering, and Isabel Moreno, Ph.D., assistant professor of psychology, are among more than 60 faculty and staff who volunteer.",
      "“Nobody told me that professors actually want you to come talk to them,” Ortega said. “I tell every student I mentor that on the first day. It sounds small, but it changes everything.”",
      { h2: "Results that justify growth" },
      "Program data show that First-Generation Scholars return for their second year at a rate of 87 percent, compared with 76 percent for first-generation students who did not participate. Their four-year graduation rate is also significantly higher.",
      "Those results persuaded the university to expand. The new funding will support additional advisors, double the size of the summer bridge, and extend the program to transfer students for the first time. Beginning this year, first-generation transfer students from community colleges will be eligible for a one-semester transition version of the program.",
      "“We had a waitlist of more than 200 students last year,” Chao said. “Turning students away from a program we know works was not acceptable.”",
      { h2: "How to join" },
      "Incoming first-year and transfer students who are the first in their families to earn a four-year degree are eligible. Applications for the spring transfer cohort are due November 15. Current students who would like to become peer mentors can apply through RedwoodConnect under the Student Affairs tab.",
      "For Lopez, the program’s growth is personal. “I want every single first-gen student who walks onto this campus to know there’s a manual now, and we wrote it for them,” she said.",
    ],
    related: ["madrone-hall-opens", "alum-california-teacher-of-year", "nursing-simulation-center-accreditation"],
    links: [
      { label: "2026–27 First-Generation Scholars Application (PDF)", href: "/documents/first-gen-scholars-application-2026-27.pdf" },
      { label: "Click here", href: "/admissions/scholarships" },
    ],
  },

  "alumna-salmon-sensor-startup": {
    date: "2026-06-10",
    author: "Megan Fairweather",
    authorTitle: "Alumni Relations",
    dek: "Tessa Moreland ’16 turned a senior research project into RiverTally, a company whose solar-powered sensors count migrating salmon for tribes, agencies and watershed groups.",
    imageCaption: "Tessa Moreland ’16 installs a RiverTally sensor on a tributary of the Silverfin River.",
    body: [
      "Tessa Moreland spent much of her senior year at Redwood State standing in cold water in the middle of the night, counting fish by flashlight. “It was the most miserable and most wonderful thing I’d ever done,” she said. “And somewhere around the third week, I started thinking there had to be a better way.”",
      "A decade later, that better way is RiverTally, the Arcadia Falls-based company Moreland co-founded in 2020. RiverTally builds solar-powered underwater sensors that use sonar and a small onboard computer to detect, count and estimate the size of salmon and steelhead as they migrate upstream. The company’s devices are now deployed on 42 rivers and streams in California, Oregon and Washington, operated by tribal fisheries programs, state agencies and local watershed councils.",
      { h2: "From a senior project to a company" },
      "Moreland graduated from RSU in 2016 with a B.S. in Biology and a minor in computer science, an unusual combination at the time. Her senior thesis, advised by faculty in both departments, compared manual night counts with an early prototype sensor she built from hobbyist electronics and a fish finder bought at a sporting goods store.",
      "The prototype was not very good, she admits. But it convinced her that accurate, affordable automated counting was possible. After graduation, she worked for four years as a fisheries technician with a tribal natural resources department, then returned to Arcadia Falls to start RiverTally with co-founder Ben Achterberg, an electrical engineer.",
      "The company has grown to 14 employees, seven of them RSU graduates, and operates out of a converted boat repair shop near the harbor. It received early support from the North Coast Small Business Center and won second place at the university’s Owl Tank pitch competition in 2020.",
      { h2: "Why counting fish matters" },
      "Salmon populations on the North Coast have declined dramatically over the past century, and several runs are listed as threatened or endangered. Accurate counts are essential for setting fishing limits, evaluating habitat restoration and understanding the effects of drought and warming water. But traditional counting methods, including weirs, traps and human observers, are labor-intensive and can stress fish.",
      "“Every restoration project on the coast is asking the same question: is it working?” Moreland said. “You can’t answer that if you don’t know how many fish came back.”",
      "RiverTally’s sensors can operate unattended for months, transmitting daily counts over cellular or satellite links. The company recently began a partnership with Ethan Park, Ph.D., assistant professor of biology, whose lab uses environmental DNA to confirm which species are present in streams where the sensors are deployed.",
      "“Tessa’s sensors tell us how many fish went by, and eDNA tells us who they were,” Park said. “Combining the two gives watershed managers a much fuller picture, and our students get to work on a real monitoring problem with a local company.”",
      { h2: "Giving back" },
      "RiverTally hosts two paid RSU interns each summer and Moreland serves on the advisory board for the College of Science. She returned to campus in April to speak to biology and computer science students about careers that cross disciplinary lines.",
      "“When I was a student, people kept asking me whether I was a biologist or a programmer, like I had to choose,” she told them. “You don’t have to choose. Some of the most interesting problems in the world live right in between.”",
      "Moreland is one of three alumni who will receive the RSU Young Alumni Achievement Award during Homecoming & Family Weekend in October.",
    ],
    related: ["tide-pool-study-coastal-warming", "alum-california-teacher-of-year", "wildfire-smoke-sensor-network"],
  },

  "library-digitizes-logging-archives": {
    date: "2026-05-27",
    author: "Staff Report",
    authorTitle: "University Communications",
    dek: "Payroll ledgers, camp photographs and oral histories from 1885 to 1985 are now freely searchable online through the Arcadia Falls Local History Archives.",
    imageCaption: "A student archivist scans a 1920s timber company payroll ledger in Sequoia Library Special Collections.",
    body: [
      "For decades, the story of Arcadia Falls’ timber industry has lived in cardboard boxes in the basement of Sequoia Library: hundreds of payroll ledgers, thousands of photographs, company maps, union newsletters, and cassette tapes of interviews with the people who worked in the woods and mills.",
      "Now, after a three-year effort, more than 140,000 pages and images from those collections are available online, free to anyone. The Arcadia Falls Logging Records Digital Collection went live this week as part of the library’s Arcadia Falls Local History Archives.",
      "“These records belong to the community,” said Yara Sullivan, dean of the library. “Many families in this region have a grandparent or great-grandparent somewhere in these ledgers. Until now, you had to come to our reading room during business hours and ask for a specific box. Today, you can search from your kitchen table.”",
      { h2: "A century of working lives" },
      "The collection spans roughly 1885 to 1985 and includes records donated by four regional timber companies, two labor unions and dozens of families. Highlights include complete payroll ledgers for the Arcadia Lumber Company from 1902 to 1958, more than 9,000 photographs of logging camps, mills, company towns and ships, and 612 oral history interviews recorded between 1994 and 2019.",
      "Those interviews were collected by the Arcadia Falls Oral History Project, founded by Harold Mensah, Ph.D., professor emeritus of history, who served as senior advisor for the digitization effort.",
      "“When I started recording these interviews in the 1990s, many of the people I talked to had worked in the woods in the 1930s and 1940s,” Mensah said. “Almost all of them are gone now. Their voices are in this collection, telling us things that never made it into any company history, about danger, about discrimination, about organizing, about joy. Making these recordings available to their grandchildren is the most meaningful thing I could imagine.”",
      { h2: "Students at the center" },
      "The work was led by Carmen Ruiz, Ph.D., associate professor of history and director of the Public History program, working with the library’s Special Collections staff. Twenty-two students worked as paid student archivists, scanning documents, transcribing handwritten ledgers and writing descriptions for each item.",
      "“A payroll ledger sounds boring until you realize it’s a list of real people,” Ruiz said. “Students found entries for Finnish immigrants, Mexican families, Black workers from the South and Native men from local tribes, often working side by side and often paid differently. The ledgers let us ask questions about who did what work and for how much.”",
      "History major Devon Achebe, who transcribed more than 3,000 ledger pages, found his own great-great-grandfather listed as a bucker at a camp on the Silverfin River in 1921. “I had heard stories, but I had never seen his name written down,” he said. “I called my grandmother from the scanning room.”",
      { h2: "Working with the community" },
      "The project team consulted with local tribes on the description of photographs and materials involving Native communities, and some culturally sensitive materials remain restricted. Transcripts are available for most oral history recordings, and the team is working to add transcripts for the remainder by spring 2027.",
      "The digitization was funded by a federal humanities preservation grant, a gift from the Arcadia Falls Historical Society and support from the Office of the Provost.",
      "Community members are invited to help identify people and places in unlabeled photographs through a crowdsourcing feature on the collection website. Special Collections will also host a series of drop-in “Find Your Family” sessions this summer.",
    ],
    related: ["first-gen-scholars-expands", "redwood-canopy-carbon-study"],
    links: [
      { label: "Arcadia Falls Local History Archives", href: "/library/guides/local-history-archives" },
      { label: "Logging Records Collection Finding Aid (PDF)", href: "/documents/logging-records-finding-aid.pdf" },
      { label: "Learn more", href: "/library" },
    ],
  },

  "wildfire-smoke-sensor-network": {
    date: "2026-09-16",
    author: "Dana Whitaker",
    authorTitle: "Office of Research Communications",
    dek: "More than 120 low-cost air quality sensors, built and installed by RSU students, now fill the gaps between official monitors from the Oregon border to the hills south of Port Alder.",
    imageCaption: "Computer science students assemble air quality sensor kits in Sequoia Engineering Hall.",
    body: [
      "When wildfire smoke rolled into the North Coast during the summer of 2024, residents of Arcadia Falls could check a government air quality monitor downtown. Families twenty miles up the Silverfin River valley had nothing, and the smoke there was often far worse.",
      "Two years later, a network of air quality sensors built by Redwood State students is filling those gaps. The North Coast Smoke Mapping project now operates 124 sensors mounted on schools, fire stations, tribal offices, libraries and farm buildings across three counties, reporting fine particle pollution every two minutes to a public online map.",
      "“Smoke doesn’t care where the official monitors are,” said Sofia Kowalski, Ph.D., assistant professor of computer science, who leads the project. “Rural communities, which are often closest to the fires, have had the least information. We wanted to change that, and we wanted students to be the ones who did it.”",
      { h2: "Designed and built by students" },
      "Each sensor is built around an inexpensive laser particle counter, a small microcontroller, a solar panel and a cellular or Wi-Fi connection. Students in Kowalski’s Senior Project section designed the circuit boards and wrote the firmware, which uses a compact machine learning model to detect and correct common errors. Mechanical engineering students designed a weatherproof housing that can be printed in the new Robotics and Autonomous Systems Lab.",
      "Over the past two summers, teams of students drove more than 8,000 miles to install and maintain sensors. Each host site signs a simple agreement and provides power or a sunny spot for the solar panel.",
      "Computer science senior Priscila Nakamura led the team that wrote the data pipeline and public map. “I’ve written a lot of code for assignments that nobody ever uses,” she said. “This summer my grandmother in Fernhaven texted me a screenshot of the map to ask whether she should close her windows. That was a good day.”",
      { h2: "The fog problem" },
      "Low-cost particle sensors have a known weakness: they can mistake water droplets for smoke. On the foggy North Coast, that is a serious problem. To address it, the project partnered with Yuki Sato, Ph.D., assistant professor of chemistry, who studies smoke and fog chemistry.",
      "Sato’s lab placed sensors alongside research-grade instruments on the roof of the Canopy Science Center for more than a year and developed a correction that accounts for humidity and fog. The results were published this year in Journal of Coastal Air Quality.",
      "“Before the correction, a foggy morning in August could look like a major smoke event,” Sato said. “Now the network is accurate enough that county public health staff are using it when they decide whether to issue smoke advisories.”",
      { h2: "Growing the network" },
      "The project has received support from a state wildfire resilience grant, the RSU Office of Research and Sponsored Programs, and a regional utility. It will add 50 sensors next year, with a focus on schools and senior centers, and is developing an alert system that will send text messages when smoke levels rise in a particular area.",
      "Kowalski said the project is also a model for how universities can work with rural communities. “We don’t just install a box and leave,” she said. “We come back, we fix things, we explain what the numbers mean. A lot of the host sites have become real partners.”",
      "The team will present its work at the Fall Undergraduate Research Symposium in November. Schools, fire stations and community organizations interested in hosting a sensor can contact the Department of Computer Science.",
      "Residents are reminded that the map is intended for general awareness only. For official air quality alerts and health guidance, consult county public health and regional air district resources.",
    ],
    related: ["engineering-robotics-lab-opens", "tide-pool-study-coastal-warming", "green-chemistry-grant"],
    links: [
      { label: "View the live smoke map", href: "https://smokemap.redwoodstate.edu" },
      { label: "Read more", href: "/academics/departments/computer-science" },
    ],
  },

  "mens-basketball-season-preview": {
    date: "2026-09-30",
    author: "Colin Reyes",
    authorTitle: "Athletics Communications",
    dek: "With eight newcomers and only two returning starters, the Owls are betting on speed, depth and junior guard Jordan Whitfield as they chase a return to the conference tournament final.",
    imageCaption: "Junior guard Jordan Whitfield drives to the basket during a preseason practice at Owl Arena.",
    body: [
      "The first thing you notice at a Redwood Owls men’s basketball practice this fall is how young everyone looks. The second is how fast they are moving.",
      "Coming off a 19–12 season that ended with a loss in the Pacific North Conference Tournament semifinals, head coach Terrence Vail is working with one of the least experienced rosters in the league. Five seniors graduated in May, including the program’s all-time leader in assists, and the Owls return only two starters. Eight of the fifteen players on the roster are in their first season with the program.",
      "Vail, entering his ninth season, is not worried. “I’d rather have a group that doesn’t know what it can’t do,” he said. “These guys are hungry, they’re coachable and they can really run. We’re going to play fast and we’re going to make people uncomfortable.”",
      { h2: "Whitfield takes the wheel" },
      "The clear leader is junior guard Jordan Whitfield, a second-team all-conference selection last season who averaged 16.4 points and 4.8 assists per game. Whitfield spent the summer working on his outside shot and, by his own admission, on becoming more vocal.",
      "“Last year I could lean on the seniors,” Whitfield said. “Now the young guys are looking at me when things get tough. I have to be the one talking in the huddle, not just the one taking the last shot.”",
      "Vail said Whitfield has embraced the role. “Jordan is the first one in the gym and the last one out,” he said. “When your best player is also your hardest worker, the young guys figure out pretty quickly what’s expected.”",
      { h2: "Lindgren back in the middle" },
      "The other returning starter is sophomore center Noah Lindgren, a 6-foot-10 native of Arcadia Falls who earned a spot on the conference all-freshman team after averaging 9.1 points and 7.3 rebounds. Lindgren added nearly 15 pounds of muscle over the offseason and has been one of the most improved players in practice.",
      "“I grew up coming to games at Owl Arena,” Lindgren said. “Playing in front of my hometown is something I don’t take for granted. This year I want to be a guy who can take over a game on both ends.”",
      "The Owls will also count on newcomers, including three transfers from California community colleges and a highly regarded freshman guard from Kestrel Bay. Vail said as many as ten players could see regular minutes early in the season.",
      { h2: "A demanding schedule" },
      "The Owls open the season at Owl Arena against longtime rival Cascade State on Friday, November 6. The early schedule also includes a home game against Westmere University the night before Thanksgiving and the Desert Palms Classic in Mirage Valley that weekend.",
      "Conference play begins November 18 at Harbor Point, with the Pacific North Conference Tournament scheduled for early March. Vail said the goal is simple: “We want to be playing our best basketball in March. If we’re doing that, we’ll be fine.”",
      "Season tickets are on sale now through the Owls ticket office in Owl Arena. RSU students are admitted free with a valid ID, and the athletics department will hold a “Blackout the Arena” promotion at the home opener, with free T-shirts for the first 1,000 students.",
      "“Owl Arena can be one of the loudest places in the conference when it’s full,” Whitfield said. “We need the students there. We feed off that.”",
    ],
    related: ["womens-soccer-conference-title", "cross-country-all-american"],
    links: [
      { label: "2026–27 Men's Basketball Schedule (PDF)", href: "/documents/mens-basketball-schedule-2026-27.pdf" },
      { label: "Click here for tickets", href: "/athletics" },
    ],
  },

  "sleep-study-later-classes": {
    date: "2026-05-06",
    author: "Dana Whitaker",
    authorTitle: "Office of Research Communications",
    dek: "After RSU pushed its earliest class start from 7:30 to 8:00 a.m., students wearing sleep trackers got about 24 more minutes of sleep a night and reported better mood.",
    imageCaption: "A student checks a wrist-worn activity monitor used in the Department of Psychology's sleep study.",
    body: [
      "Thirty minutes does not sound like much. But when Redwood State moved its earliest class start time from 7:30 to 8:00 a.m. in fall 2025, psychology researchers saw an opportunity to find out whether a half hour could make a difference in how students sleep, feel and learn.",
      "It did. In a study published this spring in the Journal of Sleep and Student Health, researchers in the Department of Psychology report that students slept an average of 24 minutes longer per night after the change, and reported fewer symptoms of depression and daytime sleepiness. Students who had early classes also missed fewer of them.",
      "“College students are among the most sleep-deprived people in the country, and it isn’t only because they stay up late,” said Kwame Asante, Ph.D., associate professor of psychology and the study’s lead author. “Their biological clocks are genuinely shifted later during these years. Asking them to be alert and learning calculus at seven-thirty in the morning is working against their biology.”",
      { h2: "A natural experiment" },
      "The schedule change was made for practical reasons, primarily to align class times with the regional bus system, and not as a research intervention. That made it an ideal natural experiment, Asante said. His team recruited 312 students in spring 2025, before the change, and 298 students in spring 2026, after it. Participants wore wrist activity monitors that track sleep for two weeks, kept sleep diaries and completed daily surveys on their phones.",
      "The research team compared students who had classes starting at the earliest time slot in each year. Students in the later-start group fell asleep at about the same time as those in the earlier group, but they woke up later and slept longer. They were also less likely to report sleeping fewer than six hours on school nights.",
      "Isabel Moreno, Ph.D., assistant professor of psychology and a co-author, said the findings on mood were especially striking. “We saw meaningful improvements in self-reported mood and reductions in daytime sleepiness,” she said. “For a policy change that cost the university essentially nothing, that’s a significant effect.”",
      { h2: "Attendance and learning" },
      "The team also worked with the Office of the Registrar and faculty in several departments to examine attendance in early classes. With student consent, they found that absences in the earliest time slot fell by about 15 percent after the change. Grades in those classes rose slightly, although the researchers caution that grades are influenced by many factors.",
      "“We want to be careful not to overclaim,” Asante said. “This is one university and one change. But it fits a large body of evidence from high schools showing that later start times help students.”",
      { h2: "Student researchers" },
      "More than twenty undergraduate psychology students worked on the study, recruiting participants, managing devices and analyzing data. Senior Nia Okonjo, who presented part of the study at a regional psychology conference, said the project changed how she thinks about her own habits.",
      "“I used to brag about getting five hours of sleep during finals,” she said. “Now I understand what that was doing to my memory. I’m kind of evangelical about sleep now. My roommates are tired of hearing about it, which is ironic.”",
      "Asante’s lab is now studying whether sleep education workshops offered during Student Wellness Week can improve sleep for students regardless of their class schedules. Students interested in participating in future studies can sign up through the Psychology Research Participation System on RedwoodConnect.",
    ],
    related: ["nursing-simulation-center-accreditation", "first-gen-scholars-expands"],
    links: [
      { label: "Study summary (PDF, 2.1 MB)", href: "/documents/sleep-study-summary-2026.pdf" },
      { label: "Read more", href: "/academics/departments/psychology" },
    ],
  },

  "alum-california-teacher-of-year": {
    date: "2026-09-10",
    author: "Megan Fairweather",
    authorTitle: "Alumni Relations",
    dek: "Rosa Delacruz-Imai ’04, M.A. ’09, a seventh-grade science teacher in Fernhaven, is the first RSU graduate to receive the state’s top teaching honor.",
    imageCaption: "Rosa Delacruz-Imai leads her seventh-grade students on a field study at the Silverfin River.",
    body: [
      "On a warm September morning, twenty-eight seventh graders from Fernhaven Middle School stood knee-deep in the Silverfin River, holding nets, thermometers and clipboards. Their teacher, Rosa Delacruz-Imai, moved from group to group asking the same question over and over: “What do you notice?”",
      "That question, and the curiosity it is meant to spark, is at the heart of a teaching career that has now earned statewide recognition. Delacruz-Imai, a 2004 graduate of Redwood State’s College of Education who later earned her master’s degree at RSU, has been named a State Teacher of the Year, one of five teachers selected from across the state. She is the first RSU graduate to receive the honor.",
      "“I was completely shocked,” Delacruz-Imai said. “There are so many incredible teachers in this state. I think of this as recognition for my students and for rural schools, which people don’t always think of as places where exciting science happens.”",
      { h2: "Science where students live" },
      "Delacruz-Imai has taught science at Fernhaven Middle School, a small rural school about thirty minutes from Arcadia Falls, for twenty-one years. She is known for building her curriculum around the places her students know: the river, the forests, the coastline and the farms where many of their parents work.",
      "Her students have monitored water quality in the Silverfin River for more than a decade, sharing their data with a regional watershed council. They have raised salmon eggs in classroom tanks for release, surveyed birds on school grounds and, in partnership with Redwood State’s North Coast Smoke Mapping project, hosted an air quality sensor on the school roof.",
      "“My students are experts on this place. They know things about the river that scientists don’t,” she said. “My job is to help them connect what they already know to the way science works.”",
      { h2: "Roots at Redwood State" },
      "Delacruz-Imai grew up in Arcadia Falls, the daughter of a fisherman and a school cafeteria worker, and was the first in her family to attend college. She earned a B.A. in Liberal Studies and her teaching credential at RSU, followed by an M.A. in Education with an emphasis in science education.",
      "She credits her RSU professors with showing her what hands-on teaching could look like. She also returns the favor: for the past twelve years she has hosted RSU student teachers in her classroom, and she has mentored more than twenty future teachers.",
      "“Rosa represents everything we hope for when we send our graduates into the world,” said President Elena Vásquez-Hart, Ph.D. “She grew up here, she learned here, and she has spent her career giving back to the young people of this region. We could not be prouder.”",
      "The College of Education plans to invite Delacruz-Imai to speak with current students in teacher preparation programs this fall.",
      { h2: "A year of service" },
      "As a State Teacher of the Year, Delacruz-Imai will spend the coming year speaking at education conferences and meeting with policymakers. She plans to focus on rural education and the recruitment of teachers from the communities they serve.",
      "“Rural schools have a hard time finding and keeping teachers,” she said. “The answer is to grow our own. If a kid from Fernhaven can see herself in the front of that classroom, she might come back and teach here someday.”",
      "Delacruz-Imai will be honored at the RSU Alumni Awards dinner during Homecoming & Family Weekend in October.",
    ],
    related: ["alumna-salmon-sensor-startup", "first-gen-scholars-expands", "wildfire-smoke-sensor-network"],
    links: [{ label: "Read more", href: "/academics/colleges/education" }],
  },

  "madrone-hall-opens": {
    date: "2026-08-24",
    author: "Jenna Albright",
    authorTitle: "University Communications",
    dek: "The first new residence hall on campus in more than thirty years welcomed its first residents this weekend, with suite-style rooms, study lounges on every floor and a rooftop garden overlooking the redwoods.",
    imageCaption: "Madrone Hall's rooftop garden looks out over the campus and the forested hills beyond.",
    body: [
      "Carts full of mini-fridges, laundry baskets and houseplants rolled across the new plaza outside Madrone Hall on Saturday as the first residents of Redwood State’s newest residence hall moved in.",
      "The five-story building, located on the north edge of campus between Canopy Green and the Rowan Student Union, adds 400 beds to university housing and is the first new residence hall built on campus since 1993. It is home primarily to first-year and second-year students.",
      "“We have had a housing shortage in Arcadia Falls for years, and our students have felt it more than anyone,” said Mei-Lin Chao, Ed.D., vice president for student affairs. “Research is clear that students who live on campus in their first year are more likely to stay in college and graduate. Madrone Hall lets us offer that experience to hundreds more students.”",
      { h2: "Designed for community" },
      "Madrone Hall is organized into four “neighborhoods” of about 100 students each, with a mix of double rooms and four-person suites. Each floor includes a large study lounge, a community kitchen and a quiet room. The ground floor houses a maker space, a music practice room, a fitness studio and the Housing & Residential Life office.",
      "Besides the Sequoia Honors community, the building houses two new living-learning communities: one for students in the First-Generation Scholars Program and one for sustainability and environmental studies students, who will help care for the rooftop garden.",
      "The garden, which covers nearly 6,000 square feet, includes raised vegetable beds, native plantings and seating areas with views of the forested ridges east of campus. Produce grown on the roof will be donated to the Owl Pantry, the university’s basic needs center.",
      "“My favorite part is the roof,” said first-year student Marcus Delaney, who moved in Saturday from Mirador Heights. “My mom went up there and said, ‘Well, now I’m jealous.’”",
      { h2: "Built for the climate" },
      "Madrone Hall was designed to meet high standards for energy efficiency and sustainability. The building uses cross-laminated timber from sustainably managed forests in the Pacific Northwest, a rainwater collection system for the garden and toilets, rooftop solar panels and heat pumps instead of natural gas.",
      "Robert Haines, M.B.A., vice president for administration and finance, said the building was designed to be both sustainable and affordable. “Our students face some of the highest housing costs in the country,” he said. “We worked hard to keep rates in Madrone close to those of our other suite-style halls, and we financed the project so that it will not increase what current students pay.”",
      "The $118 million project was financed through housing revenue bonds and completed on schedule, despite a wet winter that delayed some construction work.",
      { h2: "Accessibility and inclusion" },
      "The building includes 20 fully accessible rooms, gender-inclusive restrooms on every floor and a quiet sensory room on the ground floor. Chao said the design team met with student groups, including the Disability Justice Collective, throughout the planning process.",
      "An official dedication ceremony will be held during Homecoming & Family Weekend in October. The building is named for the Pacific madrone, a tree native to the region known for its peeling red bark.",
      "Madrone Hall is fully booked for the 2026–27 academic year. Students interested in living there next year can join the housing interest list through RedwoodConnect beginning in February.",
    ],
    related: ["first-gen-scholars-expands", "engineering-robotics-lab-opens"],
    links: [
      { label: "2026–27 Housing Rates (PDF)", href: "/documents/housing-rates-2026-27.pdf" },
      { label: "Read more", href: "/students/housing" },
    ],
  },

  "green-chemistry-grant": {
    date: "2026-07-08",
    author: "Dana Whitaker",
    authorTitle: "Office of Research Communications",
    dek: "The four-year federal award, the largest in the Chemistry department’s history, will help Professor Fatima Haddad’s lab scale up solvents made from forest and farm byproducts.",
    imageCaption: "Chemistry students work at a fume hood in the Haddad lab in the Canopy Science Center.",
    body: [
      "Every year, the chemical and pharmaceutical industries use billions of pounds of solvents, the liquids in which chemical reactions happen. Many of the most common ones are toxic, flammable and made from petroleum, and most are used once and then disposed of or burned.",
      "A Redwood State chemistry lab has spent more than a decade looking for better options. Now it has the resources to find out whether those options can work at scale.",
      "The Department of Chemistry has received a $2.4 million, four-year grant from a federal science agency to develop and test bio-based solvents made from byproducts of the regional timber and agricultural industries. The grant, led by Fatima Haddad, Ph.D., professor and chair of chemistry, is the largest single research award in the department’s history.",
      "“Solvents are the invisible part of chemistry,” Haddad said. “They make up most of the mass in a typical chemical process, and most of the waste. If we can replace them with safer solvents made from sawdust or leftover crop material, we can make a big difference without asking manufacturers to reinvent everything else.”",
      { h2: "From sawdust to solvent" },
      "Haddad’s group has developed a family of solvents derived from lignin, a tough material that gives wood its strength and is largely discarded or burned by lumber and paper mills. In a paper published last year, her team showed that one of these solvents performs as well as or better than traditional petroleum-based solvents in a class of reactions widely used to make pharmaceuticals.",
      "The new grant will allow the lab to scale up production from grams to kilograms, test the solvents in a wider range of reactions and work with industry partners to evaluate them in real manufacturing settings. It will also fund studies of what happens to the solvents when they are released into the environment.",
      "That part of the work will be led by co-investigator Daniel Brooks, Ph.D., associate professor of chemistry, who directs the department’s Instrumentation Center. “A green solvent isn’t green if it turns out to persist in rivers or break down into something toxic,” Brooks said. “We’re going to follow these molecules from start to finish.”",
      { h2: "Training the next generation" },
      "The grant includes funding for two postdoctoral researchers, three graduate students and at least twelve paid undergraduate research positions each year. Haddad said paying undergraduates is essential at a university where many students work to support themselves.",
      "“I have had brilliant students tell me they can’t do research because they need to work twenty hours a week at a restaurant,” she said. “This grant means they can do research as their job. That changes who gets to become a scientist.”",
      "Priya Natarajan, Ph.D., vice president for research and graduate studies, said the award reflects the growing strength of research at Redwood State. “Fatima’s work connects fundamental chemistry to the economy and environment of our region,” she said. “It is exactly the kind of research a public university on the North Coast should be doing.”",
      { h2: "Regional partners" },
      "The project includes partnerships with a regional lumber mill, which will provide lignin-rich byproducts, and two chemical manufacturers that will test the solvents. The team will also work with the College of Business to study the economic feasibility of producing solvents locally.",
      "Senior chemistry major Tomás Villanueva, who has worked in Haddad’s lab since his sophomore year, said the grant makes the work feel more real. “For years we’ve been making these solvents a few grams at a time,” he said. “Now we’re going to find out if they can actually replace the stuff that’s being used in factories. That’s exciting and a little terrifying.”",
      "Work under the grant began July 1.",
    ],
    related: ["redwood-canopy-carbon-study", "wildfire-smoke-sensor-network", "tide-pool-study-coastal-warming"],
    links: [{ label: "Read more", href: "/academics/departments/chemistry" }],
  },

  "cross-country-all-american": {
    date: "2026-06-01",
    author: "Colin Reyes",
    authorTitle: "Athletics Communications",
    dek: "The junior from Pine Hollow finished sixth in the 10,000 meters at the national outdoor championships, becoming the first Owls distance runner to earn All-American honors in eleven years.",
    imageCaption: "Priya Castillo leads a pack of runners during the 10,000 meters at the national outdoor championships.",
    body: [
      "With two laps to go in the 10,000 meters at the national outdoor track and field championships on Saturday night, Priya Castillo was in ninth place and running out of time. Then she started to move.",
      "Castillo passed three runners over the final 800 meters to finish sixth in 33 minutes, 41.8 seconds, a personal best by nearly twenty seconds. The finish earned her first-team All-American honors, the first for a Redwood State distance runner since 2015.",
      "“I kept telling myself, ‘You’ve done the work, now go get it,’” Castillo said after the race. “When I crossed the line and saw sixth on the board I just started crying. I’ve been dreaming about this since high school.”",
      { h2: "A cross country runner at heart" },
      "Castillo, a junior majoring in nursing, is best known on campus as the leader of the Owls cross country team, where she earned all-conference honors in each of her first two seasons. She competes in track in the spring primarily to stay sharp for the fall.",
      "“Priya is a cross country runner who happens to be very good at the track,” said head cross country and track coach Graham Torres. “She loves the hills, the mud, the chaos of a cross country race. But what she did this weekend shows she can compete with anybody on any surface.”",
      "The 10,000 meters, twenty-five laps of the track, is one of the most mentally demanding events in the sport. Castillo said she relied on lessons from cross country. “In cross country you learn to be patient and not panic when people go out fast,” she said. “Most of the girls I passed at the end went out way too hard. I just stayed calm.”",
      { h2: "Balancing the books and the miles" },
      "Castillo balances a demanding training schedule of up to 70 miles a week with the rigorous nursing curriculum, including early-morning clinical rotations. She often runs her morning workouts at 5 a.m. to make it to the Nursing Simulation Center on time.",
      "“I don’t really have a social life, but I have a very good running watch,” she joked.",
      "Castillo said her nursing faculty have been supportive. “My professors have been amazing about working with my competition schedule,” she said. “And honestly, studying for pharmacology exams on long bus rides to meets is kind of a tradition now.”",
      "She has also been named to the conference Academic All-Conference team twice, with a 3.8 grade point average.",
      { h2: "Looking ahead to the fall" },
      "Castillo’s performance sets high expectations for the upcoming cross country season, which begins with the Owl Invitational at the Arcadia Falls Community Forest course on August 29. She has set a goal of earning All-American honors in cross country at the national championships in November, and of leading the Owls women’s team to its first national championship appearance.",
      "“The team is going to be really good this year,” she said. “We have a lot of young runners who train incredibly hard. I want us to go to nationals together.”",
      "Torres said Castillo’s success is already helping in recruiting. “High school runners saw that race,” he said. “They see that you can come to Redwood State, study nursing, run in the most beautiful place in the country and be an All-American. That’s a pretty good pitch.”",
      "Castillo will spend the summer training at altitude in the mountains near Brightwater and working as a certified nursing assistant at a hospital near her hometown.",
    ],
    related: ["womens-soccer-conference-title", "mens-basketball-season-preview", "nursing-simulation-center-accreditation"],
  },
};

export const newsContent: Record<string, NewsArticle> = Object.fromEntries(
  newsArticles.map((s) => [
    s.slug,
    { slug: s.slug, title: s.name, category: s.category, image: `news-${s.slug}`, ...details[s.slug] },
  ]),
);
